import AppKit

/// One inspector row (spec §11 CI-9): the horizontal stack `inspectorRow`
/// always built — the mark gutter FIRST, with no spacing after it (CI-7) —
/// which now tracks the pointer over itself and answers a context menu.
///
/// The pointer is over the ROW, so the row tells its gutter (`hovered`); the
/// gutter decides whether that makes its ◆ a ×. The menu never reads the
/// hover: a window that is not key tracks none, and a right-click there must
/// offer the same items.
///
/// A field's or a popup's own right-click keeps its own menu, because neither
/// forwards it; the gutter, the label, a slider, a checkbox, the tags and the
/// trailing spacer reach this one.
final class InspectorRowView: NSStackView {
    let gutter: InspectorMarkGutter

    init(views: [NSView], gutter: InspectorMarkGutter) {
        self.gutter = gutter
        super.init(frame: .zero)
        for view in views { addArrangedSubview(view) }
        orientation = .horizontal
        alignment = .centerY
        spacing = 6
        setCustomSpacing(0, after: gutter)
        // As tall as the row and no taller: a fixed height would grow a row
        // of bare text (the "No filters" lines) and move everything under it.
        gutter.heightAnchor.constraint(equalTo: heightAnchor).isActive = true
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRowView does not support NSCoder")
    }

    // MARK: Hover

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Only this view's own areas: a tooltip is a tracking area too.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: .zero, options: [.mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) { setHovered(true) }
    override func mouseExited(with event: NSEvent) { setHovered(false) }

    func setHovered(_ hovered: Bool) {
        gutter.hovered = hovered
    }

    // MARK: The menu

    override func menu(for event: NSEvent) -> NSMenu? {
        contextMenu()
    }

    /// The row's items, in order: "Remove from action N" on a keyed row, "Go
    /// to action M" on a ◇ row, then — for a row with a default — "Set end
    /// value to default" with an action selected on a row that animates, else
    /// "Reset to default", disabled while the row already holds it. Nil when
    /// there would be no item.
    func contextMenu() -> NSMenu? {
        let menu = NSMenu()
        menu.autoenablesItems = false
        let binding = gutter.binding
        if gutter.isKeyed, let number = binding?.selectedActionNumber {
            add("Remove from action \(number)", #selector(removeFromAction(_:)), to: menu)
        }
        if case .other(let number) = gutter.mark {
            add("Go to action \(number)", #selector(goToAction(_:)), to: menu)
        }
        if let rowDefault = gutter.default {
            let atEnd = binding?.selectedAction != nil && gutter.animates
            let item = add(
                atEnd ? "Set end value to default" : "Reset to default",
                #selector(resetToDefault(_:)), to: menu)
            item.isEnabled = rowDefault.differs()
        }
        return menu.items.isEmpty ? nil : menu
    }

    @discardableResult
    private func add(_ title: String, _ action: Selector, to menu: NSMenu) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
        item.target = self
        menu.addItem(item)
        return item
    }

    @objc func removeFromAction(_ sender: Any?) {
        gutter.removeFromAction()
    }

    /// Selects the action the ◇ names, through the lane's own intent.
    @objc func goToAction(_ sender: Any?) {
        guard case .other(let number) = gutter.mark, let binding = gutter.binding,
              let id = binding.actionID(number: number)
        else { return }
        binding.selectAction(id)
    }

    @objc func resetToDefault(_ sender: Any?) {
        guard let rowDefault = gutter.default, let binding = gutter.binding else { return }
        binding.apply(rowDefault.name, rowDefault.ops())
    }
}
import AppKit

/// The row marks of the Clip inspector (road map 9 §5, spec §11 CI-7): what
/// the SELECTED action does to one row, in a 14 pt gutter before its label.
///
/// A row's mark is derived from two lists of `"group.key"` paths: the keys
/// its control WRITES — taken from the row's own `ops(read())` at build time,
/// so a write that lands on the action's end patch and one that lands on the
/// base props name the same key — and the keys it only FOLLOWS (Gain follows
/// Volume). Both empty is `.none`, action or no action: a row that says
/// nothing about what it writes (a readout, a Document-tab row) is never
/// marked ⊘ by omission.
enum RowMark: Equatable {
    /// Nothing to say — the gutter stays blank.
    case none
    /// ◆ — the row writes a key the selected action's end patch holds.
    case keyed
    /// ◆ and "at end" — the same, for a discrete control, which switches at
    /// the action's end rather than ramping.
    case keyedAtEnd
    /// ◇ — ANOTHER action keys it; the number is that action's time-order
    /// number (`ActionBands.ordered`).
    case other(Int)
    /// ○ — the row follows a keyed value without writing it.
    case follows
    /// ⊘ — the row writes the clip whatever is selected (CI-3, motion, a
    /// list's length): the selected action cannot animate it.
    case notAnimatable
}

/// A section's marks, folded from its gutters: how many KEYS its rows write
/// that the selected action holds (CI-6's count, so a section's `◆N` agrees
/// with its sub-tab's), whether any row is ◇, whether every row that writes
/// is ⊘, whether the section differs from its default (spec §11 CI-9), and
/// the number of the action it is EDITING — the selected one, when any of
/// its rows animates — which is what turns its Reset slot into Clear.
struct SectionMarks: Equatable {
    var keyed: Int
    var other: Bool
    var allNotAnimatable: Bool
    var differs = false
    var editing: Int? = nil

    static let empty = SectionMarks(keyed: 0, other: false, allNotAnimatable: false)
}

/// A row's default (spec §11 CI-9): the undo name its reset runs under,
/// whether the row differs from its default now, and the ops that put the
/// default back — on the base props, or on the selected action's end.
struct InspectorRowDefault {
    let name: String
    let differs: () -> Bool
    let ops: () -> [ReelOp]

    /// The default a typed row derives from its own `read` and `ops`: the
    /// value `read` answers in `.defaults`, written through `ops`.
    static func derived<T: Equatable>(
        _ binding: InspectorBinding, name: String, read: @escaping () -> T,
        ops: @escaping (T) -> [ReelOp]
    ) -> InspectorRowDefault {
        InspectorRowDefault(
            name: name,
            differs: { [weak binding] in
                guard let binding else { return false }
                return read() != binding.at(.defaults, read)
            },
            ops: { [weak binding] in
                guard let binding else { return [] }
                return ops(binding.at(.defaults, read))
            })
    }
}

/// The 14 pt column in front of every `inspectorRow`, blank at `.none`. It is
/// the row's FIRST subview, so `refreshOptionControls(in:)` refreshes it
/// before the row's controls — which is what lets its `refresh()` set the
/// label's ink and the controls' keyed border with nothing after it undoing
/// them (`OptionFieldControl.refresh()` never touches its layer).
///
/// Hovered while keyed (spec §11 CI-9) its ◆ draws as a × and a click on it
/// removes the row's keys from the selected action. The row sets `hovered`
/// (`InspectorRowView`), because the pointer is over the row, not the gutter.
final class InspectorMarkGutter: NSView, OptionControl {
    let writes: [String]
    let follows: [String]
    private(set) var mark: RowMark = .none
    private(set) weak var binding: InspectorBinding?
    let animates: Bool
    let `default`: InspectorRowDefault?
    private let discrete: Bool
    private weak var label: InspectorRowLabel?
    private let controls: [NSView]

    /// ◆ or ◆ "at end".
    var isKeyed: Bool { mark == .keyed || mark == .keyedAtEnd }
    var hovered = false {
        didSet {
            guard hovered != oldValue else { return }
            needsDisplay = true
            updateToolTip()
        }
    }
    /// The × — hover alone is not enough, the row must be keyed.
    var showsRemove: Bool { hovered && isKeyed }

    init(
        binding: InspectorBinding?, writes: [ReelOp], follows: [ReelOp],
        label: InspectorRowLabel?, controls: [NSView], discrete: Bool,
        default: InspectorRowDefault?
    ) {
        self.writes = InspectorBinding.paths(of: writes)
        self.follows = InspectorBinding.paths(of: follows)
        self.binding = binding
        self.animates = InspectorBinding.animates(writes)
        self.default = `default`
        self.discrete = discrete
        self.label = label
        self.controls = controls
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false
        widthAnchor.constraint(equalToConstant: InspectorMetrics.markGutter).isActive = true
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorMarkGutter does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    /// The keys this row writes that the selected action holds — what a
    /// section's `◆N` is the union of.
    func keyedWrites() -> Set<String> {
        guard let binding else { return [] }
        return binding.keyedPaths().intersection(writes)
    }

    /// Takes the row's keys out of the selected action's end patch — the ×
    /// and the menu's "Remove from action N".
    func removeFromAction() {
        guard let binding else { return }
        binding.apply("Remove from Action", binding.clearOps(keyedWrites()))
    }

    func refresh() {
        let next = binding?.mark(
            writes: writes, follows: follows, animates: animates, discrete: discrete) ?? .none
        if next != mark {
            mark = next
            needsDisplay = true
        }
        let ink = isKeyed ? DS.textStrong : mark == .notAnimatable ? DS.textFaint : DS.textMuted
        if let label, label.textColor != ink { label.textColor = ink }
        updateToolTip()
        paintBorders()
    }

    private func updateToolTip() {
        if showsRemove, let number = binding?.selectedActionNumber {
            toolTip = "Remove from action \(number)"
        } else if case .other(let number) = mark {
            toolTip = "Changed by action \(number)"
        } else {
            toolTip = nil
        }
    }

    /// The keyed rows' 1 pt action-ink border on their fields and popups.
    private func paintBorders() {
        let keyed = isKeyed
        for control in controls where control is OptionFieldControl
            || control is OptionPopupControl
        {
            if keyed { control.wantsLayer = true }
            guard let layer = control.layer else { continue }
            layer.borderWidth = keyed ? 1 : 0
            if keyed {
                effectiveAppearance.performAsCurrentDrawingAppearance {
                    layer.borderColor = DS.action.cgColor
                }
            }
        }
    }

    /// A `CGColor` does not follow the appearance, so the border is resolved
    /// again when it changes.
    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        paintBorders()
    }

    override func mouseDown(with event: NSEvent) {
        guard showsRemove else {
            super.mouseDown(with: event)
            return
        }
        removeFromAction()
    }

    override func draw(_ dirtyRect: NSRect) {
        let glyph: String
        let ink: NSColor
        switch mark {
        case .none: return
        case .keyed, .keyedAtEnd:
            (glyph, ink) = showsRemove ? ("×", DS.textMuted) : ("◆", DS.action)
        case .follows: (glyph, ink) = ("○", DS.action)
        case .other: (glyph, ink) = ("◇", DS.textFaint)
        case .notAnimatable: (glyph, ink) = ("⊘", DS.textFaint)
        }
        let attributes: [NSAttributedString.Key: Any] = [.font: DS.mono(10), .foregroundColor: ink]
        let size = glyph.size(withAttributes: attributes)
        glyph.draw(
            at: NSPoint(x: (bounds.width - size.width) / 2, y: (bounds.height - size.height) / 2),
            withAttributes: attributes)
    }
}

/// A short mono tag after a row's controls — "at end" in the action ink, or
/// the coral "now …" of a field-only row. Hidden while `text` answers nil.
final class InspectorRowTag: NSTextField, OptionControl {
    private let text: () -> String?

    init(text: @escaping () -> String?, color: NSColor) {
        self.text = text
        super.init(frame: .zero)
        isEditable = false
        isBordered = false
        isBezeled = false
        drawsBackground = false
        font = DS.mono(10)
        textColor = color
        // One line: a wrapping tag gives its width away to its neighbours by
        // growing tall, so a row short of room squeezed "at end" into a
        // column instead of narrowing the field beside it (B87, G-34 (l)).
        maximumNumberOfLines = 1
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRowTag does not support NSCoder")
    }

    func refresh() {
        let next = text()
        if stringValue != (next ?? "") { stringValue = next ?? "" }
        isHidden = next == nil
    }
}

/// The handoff's boxed mono 9 "clip" tag after a lone ⊘ button in an
/// animatable section — Normalize, which writes the clip whatever action is
/// selected (#102). Shown while an action is selected, CI-7's ⊘ condition.
/// Its own view: `OptionButtonControl` is shared chrome and is not forked.
final class InspectorClipTag: NSView, OptionControl {
    static let text = "clip"
    private weak var binding: InspectorBinding?

    init(binding: InspectorBinding) {
        self.binding = binding
        super.init(frame: .zero)
        toolTip = "Actions don't animate this. It changes the clip."
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorClipTag does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        let width = Self.text.size(withAttributes: [.font: DS.mono(9)]).width
        return NSSize(width: ceil(width) + 10, height: 17)
    }

    func refresh() {
        isHidden = binding?.selectedAction == nil
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.border.setStroke()
        let box = NSBezierPath(rect: bounds.insetBy(dx: 0.5, dy: 0.5))
        box.lineWidth = 1
        box.stroke()
        let attributes: [NSAttributedString.Key: Any] = [
            .font: DS.mono(9), .foregroundColor: DS.textMuted,
        ]
        let size = Self.text.size(withAttributes: attributes)
        Self.text.draw(
            at: NSPoint(x: (bounds.width - size.width) / 2, y: (bounds.height - size.height) / 2),
            withAttributes: attributes)
    }
}

// MARK: - The mark queries

extension InspectorBinding {
    /// The `"group.key"` paths a list of ops writes: `set_video`, `set_audio`
    /// and `set_text` by their patch's keys, `set_graphic` and an end's
    /// `graphic` by `graphicPaths`, `set_action_end` by each group of its
    /// patch, and `set_speed` by `speed`, the end's top-level rate key (spec
    /// §11 SR-21 (c)); every other op (a trim, a reverse) writes none.
    static func paths(of ops: [ReelOp]) -> [String] {
        let groups = ["set_video": "video", "set_audio": "audio", "set_text": "text"]
        var found = Set<String>()
        for op in ops {
            if op.name == "set_speed" {
                found.insert("speed")
                continue
            }
            guard let patch = op.args["patch"] as? [String: Any] else { continue }
            if let group = groups[op.name] {
                found.formUnion(patch.keys.map { group + "." + $0 })
            } else if op.name == "set_action_end" {
                found.formUnion(paths(inPatch: patch))
                found.formUnion(op.args["off"] as? [String] ?? [])  // keyed OFF (CI-14)
            } else if op.name == "set_graphic" { found.formUnion(graphicPaths(patch)) }
        }
        return found.sorted()
    }

    /// An end patch's paths, spelled as `paths(of:)` spells them: a top-level
    /// key that is not a group — `speed` (spec §11 SR-21 (c)) — by its own
    /// name.
    private static func paths(inPatch patch: [String: Any]) -> [String] {
        patch.flatMap { group, value -> [String] in
            if group == "graphic" { return graphicPaths(value) }
            guard let fields = value as? [String: Any] else { return group == "speed" ? [group] : [] }
            return fields.keys.map { group + "." + $0 }
        }
    }

    /// A `graphic` group's paths, `set_graphic`'s patch or an end's (spec §11
    /// G-34 (l)): `graphic.props.<key>` per prop, none for the core's
    /// `kinds`, and `graphic.<key>` for any other key — `set_graphic`'s
    /// `width`, `height` and `length`, which no end takes, so their rows are
    /// ⊘ while an action is selected.
    private static func graphicPaths(_ group: Any) -> [String] {
        guard let body = group as? [String: Any] else { return [] }
        var paths: [String] = []
        for (key, value) in body where key != "kinds" {
            if key == "props" {
                let props = (value as? [String: Any])?.keys.map { "graphic.props." + $0 }
                paths += props ?? []
            } else {
                paths.append("graphic." + key)
            }
        }
        return paths
    }

    /// Whether any of the ops reaches an action's end patch.
    static func animates(_ ops: [ReelOp]) -> Bool {
        ops.contains { $0.name == "set_action_end" }
    }

    /// The selected action's end patch, as paths.
    func keyedPaths() -> Set<String> {
        guard let action = selectedAction else { return [] }
        return Set(Self.paths(inPatch: action.end.dictionary))
    }

    /// The time-order numbers of the single selected clip's OTHER actions
    /// whose end patch holds any of `paths`. One clip only: an action's
    /// number is its clip's, and two clips' numbers would say nothing.
    func otherActions(keying paths: [String]) -> [Int] {
        guard isSingle, let clip = primary, !paths.isEmpty else { return [] }
        let wanted = Set(paths)
        let selected = selectedAction?.id
        return ActionBands.ordered(clip).enumerated().compactMap { index, action in
            guard action.id != selected,
                  !wanted.isDisjoint(with: Self.paths(inPatch: action.end.dictionary))
            else { return nil }
            return index + 1
        }
    }

    /// The selected action's time-order NUMBER on the single selected clip
    /// (`ActionBands.ordered`), nil with none selected.
    var selectedActionNumber: Int? {
        guard let id = selectedAction?.id, let clip = primary else { return nil }
        return ActionBands.ordered(clip).firstIndex { $0.id == id }.map { $0 + 1 }
    }

    /// The id of the single selected clip's action numbered `number`.
    func actionID(number: Int) -> UInt32? {
        guard isSingle, let clip = primary else { return nil }
        let ordered = ActionBands.ordered(clip)
        return ordered.indices.contains(number - 1) ? ordered[number - 1].id : nil
    }

    /// ONE `set_action_end` that nulls every `"group.key"` of `paths` in the
    /// selected action's end patch — a null REMOVES the key (spec §11 CI-9),
    /// so the value falls back to what was held. A one-part path (`speed`,
    /// spec §11 SR-21 (c)) is nulled at the patch's top. Nothing without a
    /// selected action on a single clip, or without a path.
    func clearOps(_ paths: Set<String>) -> [ReelOp] {
        guard let action = selectedAction, isSingle, let clip = primary, !paths.isEmpty
        else { return [] }
        var patch: [String: Any] = [:]
        for path in paths.sorted() {
            let parts = path.split(separator: ".", maxSplits: 1).map(String.init)
            if parts.count == 1 {
                patch[parts[0]] = NSNull()
                continue
            }
            guard parts.count == 2 else { continue }
            var group = patch[parts[0]] as? [String: Any] ?? [:]
            if parts[0] == "graphic", parts[1].hasPrefix("props.") {
                // An end's prop nests one level deeper (G-34 (a)).
                var props = group["props"] as? [String: Any] ?? [:]
                props[String(parts[1].dropFirst("props.".count))] = NSNull()
                group["props"] = props
            } else {
                group[parts[1]] = NSNull()
            }
            patch[parts[0]] = group
        }
        guard !patch.isEmpty else { return [] }
        return [.setActionEndRaw(clip: clip.id, action: action.id, patch: patch)]
    }

    /// Spec §11 CI-7's rule, in its order.
    func mark(writes: [String], follows: [String], animates: Bool, discrete: Bool) -> RowMark {
        if writes.isEmpty && follows.isEmpty { return .none }
        if selectedAction != nil {
            if !writes.isEmpty && !animates { return .notAnimatable }
            let keyed = keyedPaths()
            if !keyed.isDisjoint(with: writes) { return discrete ? .keyedAtEnd : .keyed }
            if !keyed.isDisjoint(with: follows) { return .follows }
        }
        if let number = otherActions(keying: writes + follows).first { return .other(number) }
        return .none
    }

    /// The value `read` answers at the PLAYHEAD, when the playhead is inside
    /// the first selected clip; nil otherwise.
    func nowValue(_ read: () -> Double) -> Double? {
        guard let clip = primary, clip.start <= playhead, playhead < clip.end else { return nil }
        return at(.playhead, read)
    }

    /// The value `read` answers at the selected action's START; nil with no
    /// action selected.
    func startValue(_ read: () -> Double) -> Double? {
        guard selectedAction != nil else { return nil }
        return at(.start, read)
    }
}
import AppKit

// MARK: - Slider

/// A continuous value slider whose drag is a LIVE edit: `begin` on mouse
/// down, `write` on every move, `end` on mouse up (§4.3, the document's
/// `beginLiveEdit`/`updateLiveEdit`/`endLiveEdit` trio). Paired with an
/// `OptionFieldControl` in the same row, which commits typed values as a
/// single `applyEdit` instead.
///
/// It lives here rather than in `OptionControls.swift` because that file is
/// carried verbatim from Rasterize (app/CLAUDE.md: keep it in sync, do not
/// fork); it still conforms to `OptionControl` so `refreshOptionControls`
/// finds it like every other control.
final class InspectorSliderControl: NSView, OptionControl {
    private let lower: Double
    private let upper: Double
    private let read: () -> Double
    private let write: (Double) -> Void
    private let begin: () -> Void
    private let end: () -> Void
    private let enabled: () -> Bool
    /// The value at the selected action's START and at the PLAYHEAD
    /// (`InspectorBinding.startValue` / `nowValue`), nil when there is none.
    private let start: () -> Double?
    private let now: () -> Double?
    /// Whether the row is keyed — set by `inspectorValueRow` from the row's
    /// gutter once the row exists.
    var keyed: () -> Bool = { false }
    private var isActive = true
    private var dragging = false

    init(
        min lower: Double, max upper: Double, read: @escaping () -> Double,
        write: @escaping (Double) -> Void, begin: @escaping () -> Void,
        end: @escaping () -> Void, enabled: @escaping () -> Bool,
        start: @escaping () -> Double?, now: @escaping () -> Double?
    ) {
        self.start = start
        self.now = now
        self.lower = lower
        self.upper = Swift.max(upper, lower + 0.000_001)
        self.read = read
        self.write = write
        self.begin = begin
        self.end = end
        self.enabled = enabled
        super.init(frame: .zero)
        wantsLayer = true
        setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        setContentCompressionResistancePriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        translatesAutoresizingMaskIntoConstraints = false
        widthAnchor.constraint(greaterThanOrEqualToConstant: 60).isActive = true
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSliderControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: DS.controlHeight)
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        needsDisplay = true
    }

    private var rail: InspectorRail { InspectorRail(lower: lower, upper: upper) }

    // MARK: Mouse

    override func mouseDown(with event: NSEvent) {
        guard isActive else { return }
        dragging = true
        begin()
        write(rail.value(atX: convert(event.locationInWindow, from: nil).x, width: bounds.width))
        needsDisplay = true
    }

    override func mouseDragged(with event: NSEvent) {
        guard dragging else { return }
        write(rail.value(atX: convert(event.locationInWindow, from: nil).x, width: bounds.width))
        needsDisplay = true
    }

    override func mouseUp(with event: NSEvent) {
        guard dragging else { return }
        dragging = false
        // Ends the gesture even when the value never moved: the document
        // registers no undo step for an unchanged handle, so this is free.
        end()
        needsDisplay = true
    }

    // MARK: Drawing

    override func draw(_ dirtyRect: NSRect) {
        rail.draw(
            in: self, value: read(), start: start(), now: now(), keyed: keyed(),
            keyedKnobInk: DS.textStrong.withAlphaComponent(1))
    }
}

    let gutter = InspectorMarkGutter(
        binding: binding, writes: writes, follows: follows, label: field, controls: controls,
        discrete: discrete, default: rowDefault)
    // The CONTROL gives way, never the tag (G-34 (l), O8): the row's widest
    // popup keeps its width only below the one-line tag's compression
    // resistance (750), so a keyed row short of room — Font ▸ Family's 150,
    // a filter's kind — narrows that popup to show "at end" whole. With no
    // tag showing the row has room and the popup is its full width. A row
    // with no popup gives its widest checkbox the same 749, so a module's
    // boolean with a long label narrows and the tag stays whole; the checkbox
    // draws its title from a point, so it is clipped to its own bounds rather
    // than drawing on under the tag.
    let popups: [NSView] = controls.compactMap { $0 as? OptionPopupControl }
    let checks: [NSView] = controls.compactMap { $0 as? OptionCheckboxControl }
    if let narrowing = (popups.isEmpty ? checks : popups)
        .max(by: { $0.intrinsicContentSize.width < $1.intrinsicContentSize.width })
    {
        narrowing.setContentCompressionResistancePriority(
            NSLayoutConstraint.Priority(749), for: .horizontal)
        if narrowing is OptionCheckboxControl { narrowing.clipsToBounds = true }
    }
    // A one-line name field takes the row's width, whatever its text's
    // (spec §11 G-48): it hugs nothing, and it resists compression below the
    // tag's 750, so a keyed row narrows the field to show "at end" whole and
    // a long text scrolls inside it rather than widening the row.
    for name in controls.compactMap({ $0 as? InspectorNameField }) {
        name.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        name.setContentCompressionResistancePriority(
            NSLayoutConstraint.Priority(248), for: .horizontal)
    }
    var views: [NSView] = [gutter]
    if let field {
        field.translatesAutoresizingMaskIntoConstraints = false
        field.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth).isActive = true
        views.append(field)
    }
    views.append(contentsOf: controls)
    views.append(
        InspectorRowTag(
            text: { [weak gutter] in gutter?.mark == .keyedAtEnd ? "at end" : nil },
            color: DS.action))
    if let mixed = mixed { views.append(InspectorMixedBadge(mixed: mixed)) }
    // A slider is the row's stretchy element, so a row that has one gets NO
    // trailing spacer — two views hugging at the same priority would split
    // the free space and leave the slider half as wide as it should be. The
    // Content area, a one-line name field (G-48), the Wheels row (GR-11), the
    // Curves row (GR-12) and a qualifier range's strip (GR-13) stretch the
    // same way.
    if !controls.contains(where: {
        $0 is InspectorSliderControl || $0 is InspectorTextArea || $0 is InspectorNameField
            || $0 is ColorWheelsView || $0 is CurvesView || $0 is RangeStripControl
    }) {
        let trailing = NSView()
        trailing.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        trailing.setContentCompressionResistancePriority(
            NSLayoutConstraint.Priority(1), for: .horizontal)
        views.append(trailing)
    }
    return InspectorRowView(views: views, gutter: gutter)
}

/// A row of buttons with no label column — "Fit to Canvas / Fill Canvas",
/// the text presets, the Add Action footer.
func inspectorButtonRow(_ buttons: [NSView]) -> NSView {
    let trailing = NSView()
    trailing.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
    let row = NSStackView(views: buttons + [trailing])
    row.orientation = .horizontal
    row.alignment = .centerY
    row.spacing = 6
    return row
}

/// A read-only value at the end of a row ("−6.0 dB", "00:00:04:12").
func inspectorReadout(width: CGFloat = 96, _ read: @escaping () -> String) -> OptionDisplayControl {
    OptionDisplayControl(width: width, read: read, enabled: { true })
}

/// A number bound to one property: a slider that drags LIVE beside a field
/// that commits once (spec §4.3). `ops` turns a value into the edit — the
/// binding decides whether that is a `set_video` or an action's end patch, so
/// no pane repeats that rule.
///
/// The four typed builders derive the row's default from `read` and `ops`
/// (spec §11 CI-9); `resets: false` is for a row whose `read` bypasses the
/// props readers, where a derived default could never differ.
///
/// `sliderMax` gives the slider a shorter travel than the field's `max`, for
/// a range whose top would crowd the useful part of a linear rail (Volume,
/// spec §11 AU-1): a value past it pins the knob at the rail's end, and a
/// drag writes the rail's own range.
func inspectorValueRow(
    _ label: String, _ binding: InspectorBinding, name: String, unit: String = "",
    decimals: Int = 0, min lower: Double, max upper: Double, sliderMax: Double? = nil,
    quick: [Double] = [],
    slider: Bool = true, width: CGFloat = InspectorMetrics.fieldWidth,
    read: @escaping () -> Double, ops: @escaping (Double) -> [ReelOp],
    mixed: (() -> Bool)? = nil, enabled: @escaping () -> Bool = { true },
    resets: Bool = true
) -> NSView {
    var controls: [NSView] = []
    let track = slider ? InspectorSliderControl(
        min: lower, max: sliderMax ?? upper, read: read,
        write: { [weak binding] value in binding?.liveUpdate(ops(value)) },
        begin: { [weak binding] in binding?.liveBegin() },
        end: { [weak binding] in binding?.liveEnd(name) },
        enabled: enabled,
        start: { [weak binding] in binding?.startValue(read) },
        now: { [weak binding] in binding?.nowValue(read) }) : nil
    if let track { controls.append(track) }
    controls.append(
        OptionFieldControl(
            width: width, unit: unit, decimals: decimals, min: lower, max: upper, quick: quick,
            read: read,
            write: { [weak binding] value in binding?.apply(name, ops(value)) },
            enabled: enabled,
            onEdit: { [weak binding] in binding?.edited() }))
    // A field-only row has no rail to put the playhead's tick on, so it says
    // the value in words when it differs by more than half a display unit.
    if !slider {
        controls.append(
            InspectorRowTag(
                text: { [weak binding] in
                    guard let value = binding?.nowValue(read),
                          abs(value - read()) > 0.5 * pow(10, -Double(decimals))
                    else { return nil }
                    return "now " + String(format: "%.\(decimals)f", value) + unit
                },
                color: DS.playhead))
    }
    let row = inspectorRow(
        label, controls, mixed: mixed, binding: binding, writes: ops(read()),
        default: resets ? .derived(binding, name: name, read: read, ops: ops) : nil)
    let gutter = row.gutter
    track?.keyed = { [weak gutter] in gutter?.isKeyed == true }
    return row
}

/// A boolean bound to one property. The checkbox carries its own label, so
/// the row's label column stays empty and the controls line up under the
/// numbers above them.
func inspectorCheckRow(
    _ label: String, _ binding: InspectorBinding, name: String, read: @escaping () -> Bool,
    ops: @escaping (Bool) -> [ReelOp], mixed: (() -> Bool)? = nil,
    enabled: @escaping () -> Bool = { true }, resets: Bool = true
) -> NSView {
    let check = OptionCheckboxControl(
        label: label, read: read,
        write: { [weak binding] value in binding?.apply(name, ops(value)) },
        enabled: enabled,
        onEdit: { [weak binding] in binding?.edited() })
    return inspectorRow(
        nil, [check], mixed: mixed, binding: binding, writes: ops(read()),
        default: resets ? .derived(binding, name: name, read: read, ops: ops) : nil)
}

