            },
            allNotAnimatable: !writing.isEmpty
                && writing.allSatisfy { $0.mark == .notAnimatable },
            differs: differs?() ?? gutters.contains { $0.default?.differs() == true },
            editing: gutters.contains { $0.animates } ? binding?.selectedActionNumber : nil)
